function plot(id,opt){let el=$('#'+id);if(!el||el.clientWidth<1)return;if(!charts[id])charts[id]=echarts.init(el,null,{renderer:'svg'});charts[id].setOption({animationDuration:350,color:[C.teal,C.orange,C.blue,'#a69c79'],textStyle:{fontFamily:'Segoe UI, Arial',fontSize:10,color:C.muted},aria:{enabled:true},tooltip:{trigger:'axis',confine:true,backgroundColor:'#fff',borderColor:C.line,textStyle:{fontSize:11,color:C.ink}},...opt},true);return charts[id]}
