let ys=$('#year').value==='all'?[2022,2023,2024,2025]:[+$('#year').value],metric=$('#trend-metric').value;
plot('trend',{grid:{...grid,left:65},xAxis:{...axis,type:'category',data:ys,boundaryGap:true},yAxis:{...axis,type:'value',show:false},series:[{type:'bar',barMaxWidth:50,itemStyle:{color:metric==='mortos'?C.orange:C.teal,borderRadius:[4,4,0,0]},data:ys.map(y=>(yearmap.get(y)||{})[metric]||0),label:{show:true,position:'top',formatter:o=>N(o.value),fontSize:11,color:C.ink}}]});
let byuf=[...buckets(rows,r=>REGISTROS.cats.uf[r[1]])].sort((a,b)=>b[1].mortos-a[1].mortos).slice(0,12).reverse();let rc=plot('ranking',{grid:{...grid,left:35,right:45},xAxis:{...axis,type:'value',axisLabel:{formatter:v=>N(v)}},yAxis:{...axis,type:'category',data:byuf.map(x=>x[0]),splitLine:{show:false}},series:[{type:'bar',barMaxWidth:14,data:byuf.map(x=>x[1].mortos),itemStyle:{color:C.teal,borderRadius:[0,3,3,0]},label:{show:true,position:'right',fontSize:10,formatter:o=>N(o.value)}}]});rc.off('click');rc.on('click',e=>setUF(e.name));
